// Accepts three shapes: the Error Trigger payload, the same payload passed on by
// the Error Handler, or a test item { executionId, workflowId, ... }.
const j = $json;
const ex = j.execution || {};
const wf = j.workflow || {};
const tr = j.trigger || {};
const fromTrigger = Boolean(j.execution || j.workflow || j.trigger);
return { json: {
  executionId: String(fromTrigger ? (ex.id ?? '') : (j.executionId ?? '')),
  workflowId: String(fromTrigger ? (wf.id ?? '') : (j.workflowId ?? '')),
  workflowName: String(fromTrigger ? (wf.name ?? '') : (j.workflowName ?? '')),
  failedNode: String(fromTrigger ? (ex.lastNodeExecuted ?? tr.error?.node?.name ?? '') : (j.failedNode ?? '')),
  errorMessage: String(fromTrigger ? (ex.error?.message ?? tr.error?.message ?? '') : (j.errorMessage ?? '')),
  bypass_dedup: j.bypass_dedup === true
} };

// Failures to diagnose without waiting for a new one. bypass_dedup lets you re-run them;
// real failures are deduplicated. Replace the first case with a real failed execution:
// copy the execution ID and workflow ID from your Executions list.
const cases = [
  { executionId: 'REPLACE_WITH_EXECUTION_ID', workflowId: 'REPLACE_WITH_WORKFLOW_ID' },
  // Simulated trigger-level failure: no execution exists, only the error message.
  { executionId: '', workflowId: 'sample-workflow', workflowName: 'Sample - Poll orders API', failedNode: 'Poll Orders', errorMessage: 'Polling failed: 429 Too Many Requests from the source API' }
];
return cases.map(c => ({ json: { ...c, bypass_dedup: true } }));

// Builds a compact, redacted description of the failure for the model.
// Works with full execution data, or with only the error message when the
// failure happened in a trigger (no execution exists).
// References: Skip Excluded Workflows, Get Failed Execution.
const cfg = $('Skip Excluded Workflows').item.json;
const exec = $('Get Failed Execution').item.json || {};
const wfRaw = $json || {};
const wf = Array.isArray(wfRaw.nodes) ? wfRaw : { name: cfg.workflowName, nodes: [], connections: {} };
const hasExec = Boolean(exec.data && exec.data.resultData);
const rd = hasExec ? exec.data.resultData : {};
const err = rd.error || { message: cfg.errorMessage };
const failedNode = cfg.failedNode || (err.node && err.node.name) || rd.lastNodeExecuted || '';
const nodeDef = (wf.nodes || []).find(n => n.name === failedNode) || null;
const upstream = [];
for (const [src, c] of Object.entries(wf.connections || {})) {
  for (const outs of (c.main || [])) for (const t of (outs || [])) if (t && t.node === failedNode) upstream.push(src);
}
const upRun = upstream.length && rd.runData && rd.runData[upstream[0]] ? rd.runData[upstream[0]][0] : null;
const inputSample = upRun && upRun.data && upRun.data.main && upRun.data.main[0] && upRun.data.main[0][0] ? upRun.data.main[0][0].json : null;

// Redaction: secrets and personal data never reach the model.
let redactions = 0;
const SECRET_KEY = /(authorization|token|secret|password|passwd|api[-_]?key|apikey|cookie|session|credential)/i;
function scrubString(s) {
  const before = s;
  s = s.replace(/Bearer\s+[A-Za-z0-9._~+\/-]+=*/gi, 'Bearer [REDACTED]')
       .replace(/eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]+/g, '[REDACTED_JWT]')
       .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[REDACTED_EMAIL]')
       .replace(/([?&](?:key|token|api_key|apikey|access_token|sig|signature)=)[^&\s"']+/gi, '$1[REDACTED]')
       .replace(/https:\/\/(?:ptb\.|canary\.)?discord(?:app)?\.com\/api\/webhooks\/[^\s"']+/gi, '[REDACTED_WEBHOOK]');
  if (s !== before) redactions++;
  return s.length > 600 ? s.slice(0, 600) + '...' : s;
}
function scrub(v, key) {
  if (v === null || v === undefined) return v;
  if (typeof v === 'string') {
    if (key && SECRET_KEY.test(key)) { redactions++; return '[REDACTED]'; }
    return scrubString(v);
  }
  if (Array.isArray(v)) return v.slice(0, 5).map(x => scrub(x));
  if (typeof v === 'object') { const o = {}; for (const [k, x] of Object.entries(v)) o[k] = scrub(x, k); return o; }
  return v;
}
const contextQuality = hasExec ? 'full' : 'error message only';
const context = scrub({
  workflow_name: wf.name || cfg.workflowName,
  context_available: hasExec ? 'full execution data' : 'error message only: the failure happened before an execution was recorded (for example in a trigger), or the execution data could not be read',
  failed_node: nodeDef ? { name: nodeDef.name, type: nodeDef.type, typeVersion: nodeDef.typeVersion, parameters: nodeDef.parameters } : { name: failedNode },
  upstream_nodes: upstream,
  error: { message: err.message, description: err.description, http_code: err.httpCode, type: err.name, stack_top: String(err.stack || '').split('\n').slice(0, 3).join('\n') },
  failed_node_input_sample: inputSample
});
const contextText = JSON.stringify(context, null, 1).slice(0, cfg.max_context_chars);

// Fingerprint for dedup: same workflow, node and error (numbers and IDs masked).
const errorMessage = String(err.message || cfg.errorMessage || '');
const norm = errorMessage.toLowerCase().replace(/[0-9a-f]{8,}/g, '#').replace(/\d+/g, '#').replace(/\s+/g, ' ').trim().slice(0, 200);
const fingerprint = (cfg.bypass_dedup ? 'test|' : '') + [cfg.workflowId, failedNode, norm].join('|');

const SYS = 'You are an n8n workflow failure analyst. You receive a JSON description of one failed n8n execution: the failing node definition, the error, the upstream node names, and a redacted sample of the failing node input. Explain the failure for a busy operator. Rules: use only facts in the input and never invent node names, fields or values. Values shown as [REDACTED] were removed on purpose; never treat a redaction as the bug. If context_available says error message only, base the diagnosis on the error text alone, say what extra information would confirm it, and set confidence to low or medium. If a secret appears to be typed directly into a node parameter (for example an Authorization header), say it belongs in an n8n credential. fix_type: parameter_change only when editing one node parameter would fix it and you can give the exact new value; human_required for credentials, accounts, permissions, upstream data or anything needing judgement; transient for timeouts, rate limits or outages where a retry may succeed. For human_required and transient, set fix_parameter and fix_new_value to empty strings. summary under 25 words, root_cause under 50 words, proposed_fix under 60 words. Respond only with JSON.';
const FORMAT = { type: 'object', properties: {
  summary: { type: 'string' },
  root_cause: { type: 'string' },
  category: { type: 'string', enum: ['bad_url_or_host', 'auth_or_credential', 'data_type_or_shape', 'upstream_data', 'code_error', 'timeout_or_rate_limit', 'service_unavailable', 'configuration', 'unknown'] },
  proposed_fix: { type: 'string' },
  fix_type: { type: 'string', enum: ['parameter_change', 'human_required', 'transient'] },
  fix_node: { type: 'string' },
  fix_parameter: { type: 'string' },
  fix_new_value: { type: 'string' },
  confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
  risk: { type: 'string', enum: ['low', 'medium', 'high'] }
}, required: ['summary', 'root_cause', 'category', 'proposed_fix', 'fix_type', 'fix_node', 'fix_parameter', 'fix_new_value', 'confidence', 'risk'] };

return { json: {
  workflowId: cfg.workflowId, executionId: cfg.executionId, workflowName: wf.name || cfg.workflowName, failedNode, errorMessage,
  fingerprint, contextQuality, bypass_dedup: cfg.bypass_dedup, dedup_hours: cfg.dedup_hours,
  model: cfg.model, ollama_url: cfg.ollama_url, n8n_editor_url: cfg.n8n_editor_url, redactions,
  body: { model: cfg.model, stream: false, think: false, format: FORMAT, options: { temperature: 0 }, messages: [ { role: 'system', content: SYS }, { role: 'user', content: contextText } ] }
} };

// Deterministic formatting: the model never writes the delivered message directly.
// References: Skip Repeat Failures.
const ctx = $('Skip Repeat Failures').item.json;
let d = null;
try { d = JSON.parse($json.message.content); } catch (e) { d = null; }

// Guards: never trust the model's own labels for control decisions.
let guardNote = '';
if (d && d.fix_type === 'parameter_change') {
  const param = String(d.fix_parameter || '').trim();
  const value = String(d.fix_new_value || '');
  // 1. A parameter change must name the parameter AND give the exact new value.
  if (!param || !value.trim()) {
    guardNote = 'Guard: model proposed a parameter change without an exact value, so it was downgraded to needs a human.';
  // 2. Rewriting code, or a long or multi-line value, is never a safe one-parameter fix
  //    (models have invented missing data to make code run).
  } else if (/(^|\.)(jsCode|pythonCode|code)$/i.test(param) || value.includes('\n') || value.length > 300) {
    guardNote = 'Guard: the proposal rewrites code or is longer than a one-line value, so a human must review it.';
  }
  if (guardNote) d.fix_type = 'human_required';
}
// 3. Without execution data, confidence can't be high, whatever the model says.
if (d && ctx.contextQuality !== 'full' && d.confidence === 'high') d.confidence = 'medium';

const link = '<' + ctx.n8n_editor_url + '/workflow/' + ctx.workflowId + (ctx.executionId ? '/executions/' + ctx.executionId : '') + '>';
const head = '\u{1FA7A} **Triage: ' + ctx.workflowName + '** (failed at `' + ctx.failedNode + '`)';
let lines;
if (!d || !d.summary) {
  lines = [head, 'Diagnosis unavailable: the model call failed or returned invalid JSON. The Error Handler alert above still has the raw error.', link];
} else {
  const FIX = { parameter_change: 'parameter change', human_required: 'needs a human', transient: 'retry may fix it' };
  lines = [head,
    '**What broke:** ' + d.summary,
    '**Likely cause:** ' + d.root_cause,
    '**Suggested fix:** ' + d.proposed_fix,
    '**Fix type:** ' + (FIX[d.fix_type] || d.fix_type) + ' | **Confidence:** ' + d.confidence + ' | **Risk:** ' + d.risk];
  if (d.fix_type === 'parameter_change') lines.push('**Proposed change:** `' + (d.fix_node || ctx.failedNode) + '` > `' + d.fix_parameter + '` = `' + String(d.fix_new_value) + '`');
  if (guardNote) lines.push('-# ' + guardNote);
  if (ctx.contextQuality !== 'full') lines.push('-# Based on the error message only: no execution data was available.');
  lines.push('-# ' + ctx.model + ' | ' + ctx.redactions + ' value(s) redacted before analysis | read-only, nothing was changed');
  lines.push(link);
}
const content = lines.join('\n').slice(0, 1900);
// A failed diagnosis gets a different fingerprint, so the next occurrence is retried.
return { json: { content, diagnosis: d, guarded: Boolean(guardNote),
  fingerprint: (d && d.summary ? '' : 'nodiag|') + ctx.fingerprint,
  workflowId: ctx.workflowId, workflowName: ctx.workflowName, failedNode: ctx.failedNode, errorMessage: ctx.errorMessage,
  executionId: ctx.executionId, fixType: d ? d.fix_type : 'none', model: ctx.model } };

// Drops failures already diagnosed within dedup_hours (same workflow, node and error).
// The Error Handler still alerts every time; only the AI diagnosis is skipped.
// References: Redact and Build Context.
const recent = new Set($input.all().map(i => i.json && i.json.fingerprint).filter(Boolean));
const seen = new Set();
const out = [];
for (const item of $('Redact and Build Context').all()) {
  const c = item.json;
  if (!c.bypass_dedup && (recent.has(c.fingerprint) || seen.has(c.fingerprint))) continue;
  seen.add(c.fingerprint);
  out.push({ json: c });
}
return out;
